                if k > 0:
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1] + grid[i][j] + grid[k][l])
                if l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k] + grid[i][j] + grid[k][l])
