def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        term = f'{sign}{coeff_str}{var_str}'
        terms.append(term)
    # Remove the leading '+' if present
    if terms and terms[0].startswith('+'):
        terms[0] = terms[0][1:]
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def count_partitions(n: int, k: int, x: int) -> int:
    # Base cases
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0

    # Recursive case
    # Either include a part of size x or more, or exclude it
    return count_partitions(n - x, k - 1, x) + count_partitions(n - 1, k, x + 1)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    if last == 1:
        return 1

    count = 1  # The sequence consisting of just the starting number
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd

    if y0 % x0 != 0:
        return 0

    quotient = y0 // x0
    count = 0

    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

